<?php
require __DIR__.'/src/commerce.php';
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
if($action==='login'){ $stmt=db()->prepare('SELECT id,password_hash FROM admins WHERE email=? LIMIT 1');$stmt->execute([trim($_POST['email']??'')]);$user=$stmt->fetch();if($user&&password_verify($_POST['password']??'',$user['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$user['id'];redirect('admin.php');}$error='بيانات الدخول غير صحيحة';}
elseif($action==='logout'){require_admin();$_SESSION=[];session_destroy();redirect('admin.php');}
else{require_admin();if(in_array($action,['save','delete'],true)&&!can_manage('content')){http_response_code(403);exit('ليس لديك صلاحية إدارة المحتوى');}if($action==='status'&&!can_manage('orders')){http_response_code(403);exit('ليس لديك صلاحية إدارة الطلبات');}if($action==='save'){$id=(int)($_POST['id']??0);$type=$_POST['type']??'';$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$price=($_POST['price']??'')===''?null:(float)$_POST['price'];$url=trim($_POST['external_url']??'');$image=trim($_POST['image_url']??'');$published=isset($_POST['published'])?1:0;if(!in_array($type,['project','service','product'],true)||$title===''||mb_strlen($title)>180||($price!==null&&$price<0))exit('Invalid data');foreach([$url,$image] as $link){if($link&&!filter_var($link,FILTER_VALIDATE_URL))exit('Invalid URL');if($link&&!in_array(strtolower(parse_url($link,PHP_URL_SCHEME)??''),['https','http'],true))exit('Invalid URL scheme');}if($id){$q=db()->prepare('UPDATE items SET type=?,title=?,description=?,price=?,external_url=?,image_url=?,published=? WHERE id=?');$q->execute([$type,$title,$desc,$price,$url,$image,$published,$id]);}else{$q=db()->prepare('INSERT INTO items(type,title,description,price,external_url,image_url,published) VALUES(?,?,?,?,?,?,?)');$q->execute([$type,$title,$desc,$price,$url,$image,$published]);}log_action('admin',(int)$_SESSION['admin_id'],'content_saved','item',$id?: (int)db()->lastInsertId());redirect('admin.php');}
if($action==='delete'){$q=db()->prepare('DELETE FROM items WHERE id=?');$q->execute([(int)$_POST['id']]);log_action('admin',(int)$_SESSION['admin_id'],'content_deleted','item',(int)$_POST['id']);redirect('admin.php');}
if($action==='status'){$q=db()->prepare('UPDATE requests SET status=? WHERE id=?');$status=$_POST['status']??'';if(!in_array($status,['new','in_progress','closed'],true))exit('Invalid status');$q->execute([$status,(int)$_POST['id']]);log_action('admin',(int)$_SESSION['admin_id'],'inquiry_status_changed','request',(int)$_POST['id']);redirect('admin.php');}
}}
$items=admin()?db()->query('SELECT * FROM items ORDER BY id DESC')->fetchAll():[];$requests=admin()?db()->query('SELECT * FROM requests ORDER BY id DESC LIMIT 100')->fetchAll():[];$edit=null;if(admin()&&isset($_GET['edit'])){foreach($items as $i){if($i['id']===(int)$_GET['edit'])$edit=$i;}}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&display=swap"><link rel="stylesheet" href="assets/style.css?v=2"><title>لوحة الإدارة</title></head><body><header class="site-header"><nav class="wrap site-nav"><a class="brand" href="index.php"><span class="brand-mark">ن</span><span>نَسَق<small>NASAQ DIGITAL</small></span></a><a class="btn secondary" href="index.php">عرض الموقع</a></nav></header><main class="wrap admin-shell"><section class="pagehead"><span class="eyebrow">إدارة المنصة</span><h1>لوحة تحكم نَسَق</h1><p>إدارة المحتوى ومتابعة طلبات العملاء من مكان واحد.</p></section><?php if(!admin()):?><form class="form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="login"><label>البريد<input type="email" name="email" required></label><label>كلمة المرور<input type="password" name="password" required></label><button class="btn">دخول</button><p><?=e($error)?></p></form><?php else:?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="logout"><button class="btn ghost">تسجيل الخروج</button></form><div class="admin-actions"><?php if(role()==='owner'):?><a class="btn" href="settings.php">إعدادات المنصة</a><a class="btn secondary" href="admin-activity.php">سجل النشاط</a><a class="btn secondary" href="admin-team.php">إدارة الفريق</a><?php endif;?><a class="btn secondary" href="admin-orders.php">الطلبات التجارية</a><a class="btn secondary" href="admin.php#content">إدارة المحتوى</a><a class="btn secondary" href="admin.php#requests">طلبات العملاء</a></div><div class="admin-stats"><div class="stat"><span>إجمالي المحتوى</span><strong><?=count($items)?></strong></div><div class="stat"><span>المحتوى المنشور</span><strong><?=count(array_filter($items,fn($i)=>(bool)$i['published']))?></strong></div><div class="stat"><span>طلبات العملاء المعروضة</span><strong><?=count($requests)?></strong></div></div><?php if(can_manage('content')):?><h2 id="content"><?= $edit?'تعديل محتوى':'إضافة محتوى'?></h2><form class="form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><label>القسم<select name="type"><?php foreach(['project'=>'مشروع','service'=>'خدمة','product'=>'منتج'] as $v=>$label):?><option value="<?=$v?>" <?=($edit['type']??'')===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label>العنوان<input name="title" required maxlength="180" value="<?=e($edit['title']??'')?>"></label><label>الوصف<textarea name="description" rows="4"><?=e($edit['description']??'')?></textarea></label><label>السعر (اختياري)<input type="number" min="0" step="0.01" name="price" value="<?=e(isset($edit['price'])?(string)$edit['price']:'')?>"></label><label>رابط خارجي<input type="url" name="external_url" value="<?=e($edit['external_url']??'')?>"></label><label>رابط الصورة<input type="url" name="image_url" value="<?=e($edit['image_url']??'')?>"></label><label><input type="checkbox" name="published" <?=($edit['published']??1)?'checked':''?>> منشور</label><button class="btn">حفظ المحتوى</button></form><h2>المحتوى (<?=count($items)?>)</h2><div class="tablewrap"><table><tr><th>العنوان</th><th>القسم</th><th>الحالة</th><th>إجراءات</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['title'])?></td><td><?=e($i['type'])?></td><td><?=$i['published']?'منشور':'مسودة'?></td><td><a href="admin-gallery.php?item=<?=$i['id']?>">الصور</a> · <a href="item.php?id=<?=$i['id']?>" target="_blank" rel="noopener noreferrer">معاينة</a> · <a href="?edit=<?=$i['id']?>#content">تعديل</a> <form class="inline" method="post" data-confirm="هل تريد حذف هذا العنصر نهائيًا؟"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$i['id']?>"><button>حذف</button></form></td></tr><?php endforeach;?></table></div><?php endif;?><h2 id="requests">طلبات العملاء</h2><div class="tablewrap"><table><tr><th>العميل</th><th>الطلب</th><th>الرسالة</th><th>الحالة</th></tr><?php foreach($requests as $r):?><tr><td><?=e($r['name'])?><br><?=e($r['email'])?></td><td><?=e($r['category'])?></td><td><?=nl2br(e($r['message']))?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach(['new'=>'جديد','in_progress'=>'قيد التنفيذ','closed'=>'مغلق'] as $v=>$label):?><option value="<?=$v?>" <?=$r['status']===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select><button>تحديث</button></form></td></tr><?php endforeach;?></table></div><?php endif;?></main><script src="assets/app.js?v=2" defer></script></body></html>